INSERT INTO public.review VALUES (1, 1, 1, 5, 'Exceptional thermal performance! Even after continuous high-resolution camera recordings and heavy benchmark testing, the device stays remarkably cool with zero thermal throttling. Retail customers praise its battery endurance.', '2026-11-16 17:14:57.840349+00');
INSERT INTO public.review VALUES (2, 1, 4, 4, 'Great camera system, especially in low light night portrait mode. The chipset handles heavy background applications without stutter. Highly recommended for commercial buyers.', '2026-11-16 17:14:57.841133+00');
INSERT INTO public.review VALUES (3, 1, 7, 4, 'Reliable workhorse device. Water resistance and shatter protection have made this very popular among our enterprise logistics clients.', '2026-11-16 17:14:57.841524+00');
INSERT INTO public.review VALUES (4, 1, 10, 4, 'Impressive build materials and clean software. Rapid 100W charging is a huge selling point on the retail counter. Will reorder in larger batch.', '2026-11-16 17:14:57.841961+00');
INSERT INTO public.review VALUES (5, 1, 13, 4, 'Solid wholesale stock item. The battery easily lasts a full day under demanding usage. Fast charging is reliable, and build quality feels truly premium.', '2026-11-16 17:14:57.842268+00');
INSERT INTO public.review VALUES (6, 1, 16, 5, 'Superb vapor chamber cooling architecture! Gamers specifically ask for this model because frame rates stay locked at 120fps without drops. Fast stock turnover.', '2026-11-16 17:14:57.842584+00');
INSERT INTO public.review VALUES (7, 1, 19, 2, 'Camera quality is acceptable, but battery drain during continuous 5G navigation is higher than expected. Slower inventory turnaround in our regional market.', '2026-11-16 17:14:57.842906+00');
