INSERT INTO public.spec_sheet VALUES (1, 1, 'The iPhone 15 Pro Max represents the pinnacle of Apple hardware engineering for wholesale buyers. Built with an aerospace-grade titanium frame and an internal aluminum thermal dissipation matrix, it prevents thermal throttling during 4K ProRes LOG capture. The 48MP quad-pixel sensor and dedicated 5x telephoto lens deliver class-leading computational photography. Supported by 120Hz ProMotion OLED screen and A17 Pro silicon, this flagship delivers sustained high frame rates and superior battery endurance across enterprise and demanding retail usage.', '6.7-inch Super Retina XDR OLED, 2796x1290 pixels, 120Hz ProMotion, 2000 nits peak outdoor brightness, Ceramic Shield.', 'Triple array: 48MP main with second-gen sensor-shift OIS, 12MP 5x telephoto periscope zoom, 12MP ultra-wide with macro autofocus, 4K60 ProRes LOG video recording.', 'Apple A17 Pro (3nm), 6-core CPU with 2 performance and 4 efficiency cores, 6-core GPU with hardware-accelerated ray tracing, 16-core Neural Engine.', '4422mAh lithium-ion battery, 29 hours video playback, 50% charge in 30 minutes with 20W+ adapter, 15W MagSafe wireless.', 'Titanium substructure with internal aluminum diffusion frame engineered for heat dissipation during sustained gaming and video recording.', '2026-11-16 17:14:57.100588+00');
INSERT INTO public.spec_sheet VALUES (2, 2, 'Apple iPhone 15 Pro offers flagship power in a manageable 6.1-inch form factor. With aerospace titanium construction and advanced heat distribution, the device handles sustained GPU loads with minimal frame drops. The pro camera module features 48MP resolution and 3x optical magnification. Ideal for retail customers seeking compact pro performance without compromising on screen brightness or computational video capabilities.', '6.1-inch Super Retina XDR OLED, 2556x1179 pixels, 120Hz ProMotion, Always-On display, Dynamic Island, 2000 nits brightness.', '48MP main sensor with sensor-shift OIS, 12MP 3x telephoto optical zoom, 12MP ultra-wide, 4K Cinematic video mode at 24fps and 30fps.', 'Apple A17 Pro (3nm), 6-core CPU, 6-core GPU with dedicated ray-tracing hardware, USB 3 controller supporting 10Gbps data transfer.', '3274mAh battery providing up to 23 hours video playback, 50% recharge in 30 minutes via USB-C PD, MagSafe wireless.', 'Compact aluminum chassis heat spreader designed to distribute thermal load evenly across the rear glass enclosure.', '2026-11-16 17:14:57.102615+00');
INSERT INTO public.spec_sheet VALUES (3, 3, 'The standard iPhone 15 brings high-end features to the mainstream wholesale market. Featuring the Dynamic Island and an upgraded 48MP camera system, it captures stunning high-resolution photos with 2x lossless zoom. The A16 Bionic delivers smooth operation while maintaining low thermal profiles. High durability and strong retail resale value make this a primary volume driver for distributor sales.', '6.1-inch Super Retina XDR OLED, 2556x1179 pixels, 60Hz, Dynamic Island, HDR10, Dolby Vision, 2000 nits peak brightness.', 'Dual setup: 48MP main camera with 2x optical quality telephoto crop, 12MP ultra-wide, 4K Dolby Vision HDR video up to 60fps.', 'Apple A16 Bionic (4nm), 6-core CPU with 2 performance cores and 4 efficiency cores, 5-core GPU, 16-core Neural Engine.', '3349mAh capacity, all-day 20-hour video battery endurance, USB-C universal charging interface.', 'Passive thermal cooling architecture optimized for cool operation during daily social streaming, GPS navigation, and video calls.', '2026-11-16 17:14:57.103281+00');
INSERT INTO public.spec_sheet VALUES (4, 4, 'iPhone 14 offers established reliability and exceptional battery efficiency for enterprise and commercial bulk buyers. Equipped with the proven A15 Bionic processor and dual 12MP Photonic camera array, it delivers crisp low-light imagery and smooth 4K video. Low return rates and consistent market demand make it a cornerstone of wholesale phone inventories.', '6.1-inch Super Retina XDR OLED, 2532x1170 pixels, HDR10, Ceramic Shield front glass, 1200 nits peak brightness.', 'Dual 12MP system with sensor-shift optical image stabilization, Photonic Engine, 4K Cinematic video recording.', 'Apple A15 Bionic with 5-core GPU, 6-core CPU, 16-core Neural Engine for fast on-device machine learning.', '3279mAh cell, up to 20 hours video playback, fast charging compatible with 20W chargers.', 'Solid internal thermal dissipation layout keeping surface temperatures stable under continuous load.', '2026-11-16 17:14:57.103984+00');
INSERT INTO public.spec_sheet VALUES (5, 5, 'The iPhone 13 remains a high-volume wholesale champion due to its competitive pricing and modern design. It pairs vibrant OLED visuals with reliable dual cameras and durable Ceramic Shield protection. Retailers benefit from fast stock turns and strong consumer brand loyalty across tier-1 and tier-2 mobile markets.', '6.1-inch Super Retina XDR OLED, 2532x1170 pixels, True Tone, Wide color P3, 1200 nits peak HDR brightness.', 'Dual 12MP wide and ultra-wide cameras, sensor-shift OIS, Night mode, Smart HDR 4, 4K Dolby Vision video recording.', 'Apple A15 Bionic (5nm), 4-core GPU, 6-core CPU delivering exceptional sustained throughput.', '3227mAh battery with 19 hours video playback capability, wireless Qi and MagSafe charging.', 'Standard passive aluminum frame heat conduction with dependable thermal regulation.', '2026-11-16 17:14:57.10475+00');
INSERT INTO public.spec_sheet VALUES (6, 6, 'iPhone SE 3rd Gen blends the pocketable, iconic Touch ID form factor with the blazing speed of Apple A15 Bionic silicon and 5G connectivity. Ideal for corporate fleets and budget-conscious retail consumers wanting genuine iOS security and camera quality in a compact, durable package.', '4.7-inch Retina HD IPS LCD, 1334x750 pixels, True Tone, wide color display, physical Home button with Touch ID.', '12MP wide camera, f/1.8 aperture, portrait mode with depth control, Smart HDR 4, 4K video up to 60fps.', 'Apple A15 Bionic processor, 5G wireless connectivity, 16-core Neural Engine.', '2018mAh compact battery with fast charging support up to 50% in 30 minutes.', 'Efficient low-wattage operation with minimal heat generation across everyday communications.', '2026-11-16 17:14:57.105391+00');
INSERT INTO public.spec_sheet VALUES (7, 7, 'Samsung Galaxy S24 Ultra is the premier Android business and gaming flagship. Engineered with a titanium frame and an oversized vapor chamber nearly double the size of its predecessor, it dissipates heat effortlessly during intensive gaming and 8K video sessions. The 200MP camera and 5x optical periscope capture razor-sharp imagery, while Galaxy AI automates transcriptions and image generation. Retail demand is consistently high among high-ticket power users.', '6.8-inch Dynamic AMOLED 2X, QHD+ 3120x1440, 1-120Hz LTPO, flat glass, Corning Gorilla Armor anti-reflective coating, 2600 nits.', 'Quad system: 200MP main sensor with OIS, 50MP periscope 5x optical zoom, 10MP 3x telephoto, 12MP ultra-wide, 8K30 and 4K120 video capture.', 'Qualcomm Snapdragon 8 Gen 3 for Galaxy, Adreno 750 GPU, NPU designed for on-device Galaxy AI processing.', '5000mAh long-lasting cell, 45W wired fast charging, 15W wireless charging, reverse wireless PowerShare.', 'Enlarged 1.9x vapor chamber cooling system with multi-layer graphite sheets ensuring cool gaming and continuous 4K video capture.', '2026-11-16 17:14:57.106012+00');
INSERT INTO public.spec_sheet VALUES (8, 8, 'The Galaxy S24 Plus pairs a stunning QHD+ 120Hz AMOLED display with enhanced thermal engineering and a massive 4900mAh battery. Its 12GB base RAM and AI-driven imaging suite provide exceptional performance for demanding retail customers who want a large display without the bulk of the Ultra.', '6.7-inch Dynamic AMOLED 2X, QHD+ 3120x1440 pixels, 1-120Hz adaptive refresh rate, 2600 nits peak brightness.', 'Triple rear array: 50MP main with Dual Pixel AF and OIS, 10MP 3x telephoto, 12MP ultra-wide, Super HDR video.', 'Exynos 2400 / Snapdragon 8 Gen 3 with 12GB LPDDR5X RAM and advanced thermal throttling prevention.', '4900mAh high-density battery supporting 45W fast wired charging and Fast Wireless Charging 2.0.', 'Substantial copper vapor chamber providing effective heat spread and low peak skin temperatures.', '2026-11-16 17:14:57.106593+00');
INSERT INTO public.spec_sheet VALUES (9, 9, 'The Galaxy S24 offers flagship processing, Galaxy AI integration, and bright 2600-nit display in an ergonomic 6.2-inch body. Its reinforced Armor Aluminum frame and vapor chamber cooling ensure sustained productivity and photography performance, making it a reliable wholesale stock item.', '6.2-inch Dynamic AMOLED 2X, FHD+ 2340x1080 pixels, 1-120Hz LTPO, 2600 nits peak brightness, Armor Aluminum frame.', '50MP wide camera with OIS, 10MP telephoto with 3x optical zoom, 12MP ultra-wide, 8K video recording.', 'Exynos 2400 / Snapdragon 8 Gen 3 with high-efficiency multi-threaded processing.', '4000mAh battery with 25W fast wired charging and wireless charging.', 'Integrated vapor chamber cooling designed into a slim, pocketable aluminum chassis.', '2026-11-16 17:14:57.107203+00');
INSERT INTO public.spec_sheet VALUES (10, 10, 'The Galaxy S23 Fan Edition delivers near-flagship camera capabilities, premium glass and aluminum design, and liquid cooling at an aggressive wholesale price point. The 50MP primary sensor and dedicated 3x telephoto make it very popular among business buyers seeking premium value.', '6.4-inch Dynamic AMOLED 2X, FHD+, 120Hz adaptive refresh rate, HDR10+, Corning Gorilla Glass 5.', '50MP main sensor with OIS, 8MP 3x telephoto camera, 12MP ultra-wide, 4K60 video recording.', 'Exynos 2200 / Snapdragon 8 Gen 1 processor with high-speed 8GB RAM.', '4500mAh cell with 25W wired charging and 15W wireless charging.', 'Dedicated vapor chamber maintaining stable processor clock speeds during prolonged gaming sessions.', '2026-11-16 17:14:57.107866+00');
INSERT INTO public.spec_sheet VALUES (11, 11, 'Samsung Galaxy Z Fold 5 dominates the premium foldable enterprise segment. With zero-gap hinge mechanics, dual-display multitasking, and S-Pen compatibility, it turns mobile workflows into seamless productivity. Durable Armor Aluminum and IPX8 waterproofing provide peace of mind for wholesale buyers.', 'Main: 7.6-inch Foldable Dynamic AMOLED 2X, 120Hz; Cover: 6.2-inch Dynamic AMOLED 2X, 120Hz.', '50MP main with Dual Pixel AF and OIS, 10MP 3x telephoto, 12MP ultra-wide, under-display selfie camera.', 'Snapdragon 8 Gen 2 for Galaxy, 12GB RAM, optimized for multi-window multitasking.', '4400mAh dual-cell battery with 25W fast wired charging.', 'Dual-chassis thermal dispersion system ensuring optimal heat mitigation across both folding halves.', '2026-11-16 17:14:57.108479+00');
INSERT INTO public.spec_sheet VALUES (12, 12, 'The Galaxy Z Flip 5 brings innovative clamshell portability and a full-size 3.4-inch Flex Window cover screen. Customers can reply to messages, snap selfies using the main 12MP sensors, and control multimedia without unfolding the device. High aesthetic appeal makes it a strong retail seller.', 'Main: 6.7-inch Foldable Dynamic AMOLED 2X, 120Hz; Flex Window: 3.4-inch Super AMOLED cover screen.', 'Dual 12MP wide and ultra-wide cameras with FlexCam hands-free shooting and 4K60 video.', 'Snapdragon 8 Gen 2 for Galaxy with 8GB RAM and high power efficiency.', '3700mAh dual battery system with 25W wired fast charge.', 'Slim internal graphite heat shields preventing hot spots during extended cover-screen video calls.', '2026-11-16 17:14:57.109041+00');
INSERT INTO public.spec_sheet VALUES (13, 13, 'Samsung Galaxy A55 5G bridges mid-range pricing with flagship build quality, boasting metallic side rails, Gorilla Glass Victus+, and an AMD-powered Exynos GPU. The integrated vapor chamber keeps temperatures low during extended gaming and streaming, driving massive wholesale order volume.', '6.6-inch Super AMOLED, FHD+ 2340x1080 pixels, 120Hz refresh rate, 1000 nits high brightness mode, Vision Booster.', '50MP main with OIS, 12MP ultra-wide, 5MP macro, 4K video recording with VDIS digital stabilization.', 'Exynos 1480 (4nm) with AMD Xclipse 530 GPU, 8GB/12GB RAM.', '5000mAh battery with 25W fast wired charging, 2-day battery life profile.', 'Expanded vapor chamber cooling providing superior thermal dissipation over previous generations.', '2026-11-16 17:14:57.109621+00');
INSERT INTO public.spec_sheet VALUES (14, 14, 'The Galaxy A35 5G is a wholesale staple offering premium Super AMOLED 120Hz visuals and reliable 50MP optical image stabilization at a volume-friendly wholesale cost. IP67 water resistance and 4 years of OS upgrades guarantee steady retail turnover.', '6.6-inch Super AMOLED, FHD+ 2340x1080, 120Hz, Infinity-O display, 1000 nits peak brightness.', '50MP main camera with OIS, 8MP ultra-wide, 5MP macro lens, 4K UHD recording.', 'Exynos 1380 (5nm), octa-core CPU, ARM Mali-G68 GPU, 6GB/8GB RAM.', '5000mAh battery with 25W fast charging support and IP67 dust and water resistance.', 'Internal heat spreading sheets maintaining comfortable hand feel under sustained 5G streaming.', '2026-11-16 17:14:57.110237+00');
INSERT INTO public.spec_sheet VALUES (15, 15, 'Google Pixel 8 Pro delivers world-class computational photography with unmatched photo and video magic features. Tensor G3 silicon handles on-device generative AI, Video Boost, and Audio Magic Eraser. Dedicated copper thermal channeling ensures sustained processing performance during intensive camera workflows.', '6.7-inch Super Actua LTPO OLED, 2992x1344 pixels, 1-120Hz, 2400 nits peak brightness, Gorilla Glass Victus 2.', '50MP Octa PD main with OIS, 48MP Quad PD telephoto with 5x optical zoom and 30x Super Res Zoom, 48MP ultra-wide with Macro Focus.', 'Google Tensor G3 with Titan M2 security coprocessor, 12GB LPDDR5X RAM, machine learning acceleration.', '5050mAh battery with 30W wired charging and 23W wireless fast charging.', 'Custom copper heat-pipe assembly designed to regulate Tensor G3 thermal output during multi-frame Night Sight rendering.', '2026-11-16 17:14:57.110827+00');
INSERT INTO public.spec_sheet VALUES (16, 16, 'The Pixel 8 packs Google AI leadership and the Tensor G3 chipset into an ultra-comfortable 6.2-inch form factor. With 7 years of promised software and security upgrades, it delivers tremendous long-term value for commercial clients and retail consumers alike.', '6.2-inch Actua OLED, 2400x1080 pixels, 60-120Hz refresh rate, 2000 nits peak brightness, Corning Gorilla Glass Victus.', '50MP Octa PD wide camera with OIS, 12MP ultra-wide with auto-focus and macro mode, 4K60 video.', 'Google Tensor G3, 8GB LPDDR5X RAM, Google AI voice transcription and photo editing.', '4575mAh battery with 27W fast charging, 24+ hour battery life, Extreme Battery Saver up to 72 hours.', 'Efficient internal graphite thermal layers keeping surface heat well-regulated.', '2026-11-16 17:14:57.111493+00');
INSERT INTO public.spec_sheet VALUES (17, 17, 'Pixel 7a delivers flagship-tier camera results at a mid-tier price point. Featuring Tensor G2, 64MP high-resolution sensor, and wireless charging, it represents an outstanding return on investment for wholesale inventory turnover.', '6.1-inch OLED, FHD+ 2400x1080 pixels, 90Hz Smooth Display, HDR, Corning Gorilla Glass 3.', '64MP main camera with OIS and Super Res Zoom up to 8x, 13MP ultra-wide camera with 120-degree FOV.', 'Google Tensor G2 with Titan M2 security coprocessor, 8GB LPDDR5 RAM.', '4385mAh battery with 18W wired charging and Qi wireless charging support.', 'Balanced thermal profile engineered for smooth day-to-day operation.', '2026-11-16 17:14:57.112153+00');
INSERT INTO public.spec_sheet VALUES (18, 18, 'Google Pixel 8a democratizes cutting-edge Google AI photo features. With the powerful Tensor G3 engine, 120Hz Actua screen, and seven full years of updates, it provides unrivaled shelf life and strong commercial appeal for wholesale distributors.', '6.1-inch Actua OLED, 2400x1080 pixels, 120Hz refresh rate, 2000 nits peak brightness, matte composite back.', '64MP Quad PD main camera with OIS, 13MP ultra-wide, Real Tone, Night Sight, Best Take, Magic Editor.', 'Google Tensor G3 processor, 8GB RAM, 7 years of OS and feature drops.', '4492mAh battery, fast wired charging, Qi certified wireless charging.', 'Redesigned internal heat spreading architecture ensuring cool operational temps during prolonged video recording.', '2026-11-16 17:14:57.112781+00');
INSERT INTO public.spec_sheet VALUES (19, 19, 'The OnePlus 12 is an absolute beast for mobile gamers and tech enthusiasts. Its massive 9140mm² dual-layer vapor chamber keeps the Snapdragon 8 Gen 3 frosty under 120fps gaming conditions without throttling. Paired with a stunning 4500-nit ProXDR 2K display, 100W fast charging, and 5400mAh battery, it commands fierce demand in retail distribution.', '6.82-inch 2K ProXDR AMOLED, 3168x1440 pixels, 1-120Hz LTPO 3.0, 4500 nits peak brightness, 2160Hz PWM dimming.', 'Hasselblad camera system: 50MP Sony LYT-808 main with OIS, 64MP 3x periscope telephoto, 48MP ultra-wide, 4K Dolby Vision video.', 'Qualcomm Snapdragon 8 Gen 3, up to 16GB LPDDR5X RAM, Trinity Engine CPU/GPU scheduling.', '5400mAh dual-cell battery, 100W SuperVOOC wired charging (1-100% in 26 minutes), 50W AirVOOC wireless.', 'Dual Cryo-velocity VC cooling system featuring 9140mm² total vapor chamber area for extreme gaming thermal dissipation.', '2026-11-16 17:14:57.113452+00');
INSERT INTO public.spec_sheet VALUES (20, 20, 'OnePlus 12R is the ultimate value-flagship powerhouse. Featuring the largest battery ever in a OnePlus device (5500mAh) and 100W ultra-fast charging, it pairs with the flagship Cryo-velocity cooling system to deliver marathon high-FPS gaming sessions without thermal slowdowns.', '6.78-inch 1.5K Oriental AMOLED, 2780x1264 pixels, 1-120Hz LTPO, 4500 nits peak brightness, Aqua Touch tech.', '50MP Sony IMX890 with OIS, 8MP ultra-wide, 2MP macro, 4K60 video recording.', 'Snapdragon 8 Gen 2, up to 16GB LPDDR5X RAM, dedicated gaming graphics boost.', '5500mAh massive battery, 100W SuperVOOC fast charging (1-100% in 27 minutes).', 'Advanced 9140mm² Cryo-Velocity vapor chamber providing desktop-grade thermal efficiency.', '2026-11-16 17:14:57.114146+00');
INSERT INTO public.spec_sheet VALUES (21, 21, 'OnePlus Open redefines foldable technology with a lightweight titanium-alloy hinge, virtually invisible crease, and Pixel Stacked camera optics. The revolutionary Open Canvas interface allows simultaneous multi-app execution without thermal lag, making it a prestigious wholesale flagship.', 'Main: 7.82-inch Flexi-fluid 2K AMOLED, 120Hz; Cover: 6.31-inch Super Fluid AMOLED, 120Hz, 2800 nits.', 'Hasselblad 48MP Sony LYT-T808 Pixel Stacked main, 64MP 3x periscope telephoto, 48MP ultra-wide.', 'Snapdragon 8 Gen 2, 16GB LPDDR5X RAM, Open Canvas multi-app multitasking workspace.', '4805mAh battery with 67W SuperVOOC flash charging.', 'Multi-directional thermal graphite architecture dissipating heat across both halves of the folding chassis.', '2026-11-16 17:14:57.114771+00');
INSERT INTO public.spec_sheet VALUES (22, 22, 'OnePlus Nord 4 delivers a rare, striking all-metal unibody housing modern 5G antennas. Driven by the Snapdragon 7+ Gen 3 processor, it offers near-flagship speeds, a massive 5500mAh battery, and 100W charging, quickly becoming a top seller across retail electronics stores.', '6.74-inch 1.5K AMOLED, 2772x1240 pixels, 120Hz, 2150 nits peak brightness, Ultra HDR support.', '50MP Sony LYT-600 main with OIS, 8MP ultra-wide 112-degree FOV, 4K60 video recording.', 'Qualcomm Snapdragon 7+ Gen 3 (4nm), 8GB/12GB LPDDR5X RAM, AI Eraser and AI Summary.', '5500mAh battery with 100W SuperVOOC fast charging.', 'Precision-machined all-metal unibody with internal graphite-heatpipe hybrid thermal dispersion.', '2026-11-16 17:14:57.115377+00');
INSERT INTO public.spec_sheet VALUES (23, 23, 'OnePlus Nord CE4 delivers 100W rapid charging and a 5500mAh battery at an accessible wholesale tier. With expandable storage up to 1TB and smooth 120Hz AMOLED viewing, it is an essential inventory item for high-turnover retailers.', '6.7-inch FHD+ AMOLED, 2412x1080 pixels, 120Hz refresh rate, Aqua Touch wet hand control.', '50MP Sony LYT-600 with OIS, 8MP ultra-wide, RAW HDR photography algorithms.', 'Snapdragon 7 Gen 3 (4nm), 8GB LPDDR4X RAM, expandable RAM up to 16GB.', '5500mAh capacity cell, 100W SuperVOOC charging, charge health preservation up to 4 years.', 'High-density graphite cooling structure keeping charging temperatures remarkably cool.', '2026-11-16 17:14:57.115944+00');
INSERT INTO public.spec_sheet VALUES (24, 24, 'Xiaomi 14 Ultra is the pinnacle of optical mobile imaging. Its mechanical stepless variable aperture and 1-inch Sony sensor combine with Leica color tuning for unmatched low-light and portrait clarity. The dual-channel IceLoop cooling system maintains high processing frame rates during extensive 8K video capture, representing a top-tier wholesale asset.', '6.73-inch WQHD+ LTPO AMOLED, 3200x1440, 1-120Hz, 3000 nits peak brightness, Xiaomi Shield Glass, Dolby Vision.', 'Quad 50MP Leica optics: 1-inch Sony LYT-900 main with stepless variable aperture f/1.63-f/4.0, 50MP 3.2x telephoto, 50MP 5x periscope, 50MP ultra-wide, 8K video.', 'Snapdragon 8 Gen 3, up to 16GB LPDDR5X RAM, UFS 4.0 storage, Xiaomi HyperOS.', '5000mAh battery with 90W HyperCharge wired and 80W wireless fast charging.', 'Dual-channel IceLoop vapor-liquid separation cooling system keeping the 1-inch sensor and processor cool during continuous 8K filming.', '2026-11-16 17:14:57.116485+00');
INSERT INTO public.spec_sheet VALUES (25, 25, 'Xiaomi 14 combines compact dimensions with uncompromising flagship performance. Featuring a 6.36-inch display with razor-thin bezels and high-grade Leica Summilux lenses, it delivers superior photographic quality. The IceLoop cooling loop ensures optimal performance during gaming, driving strong wholesale demand.', '6.36-inch 1.5K CrystalRes AMOLED, 2670x1200, 1-120Hz LTPO, 3000 nits peak brightness, ultra-thin 1.61mm bezels.', 'Triple 50MP Leica cameras: 50MP Light Fusion 900 main with OIS, 50MP 3.2x floating telephoto with macro, 50MP ultra-wide.', 'Snapdragon 8 Gen 3, 12GB LPDDR5X RAM, Xiaomi HyperOS.', '4610mAh battery with 90W wired HyperCharge (1-100% in 31 minutes) and 50W wireless.', 'Xiaomi IceLoop cooling technology delivering three times the thermal efficiency of traditional vapor chambers.', '2026-11-16 17:14:57.117072+00');
INSERT INTO public.spec_sheet VALUES (26, 26, 'Redmi Note 13 Pro+ 5G represents the apex of the beloved Redmi Note series. It features a curved 1.5K AMOLED display, IP68 flagship waterproofing, 120W lightning-fast charging, and a 200MP camera with OIS. An indispensable volume generator for mobile distributors.', '6.67-inch 1.5K 120Hz 3D curved CrystalRes AMOLED, 2712x1220 pixels, 1800 nits peak, Corning Gorilla Glass Victus.', '200MP Samsung ISOCELL HP3 main with OIS and 4x lossless in-sensor zoom, 8MP ultra-wide, 2MP macro, 4K30 video.', 'MediaTek Dimensity 7200-Ultra (4nm), up to 12GB RAM, IP68 water and dust resistance.', '5000mAh battery with 120W HyperCharge (100% in 19 minutes).', '4000mm² graphite sheets and heat dissipating silicone preventing heating during 120W charge cycles.', '2026-11-16 17:14:57.117715+00');
INSERT INTO public.spec_sheet VALUES (27, 27, 'Redmi Note 13 Pro 5G delivers sharp 200MP photography and an immersive 1.5K flat display with minimal bezels. Its dependable Snapdragon processor and 5100mAh battery offer consistent day-long endurance, establishing it as a top wholesale selection.', '6.67-inch 1.5K flat AMOLED, 2712x1220, 120Hz refresh rate, 1800 nits peak brightness, Dolby Vision.', '200MP main camera with OIS and Super QPD autofocus, 8MP ultra-wide, 2MP macro.', 'Snapdragon 7s Gen 2 (4nm), 8GB/12GB RAM, dual stereo speakers with Dolby Atmos.', '5100mAh battery with 67W turbo charging.', 'Graphene heat dissipation layer providing solid thermal balance during casual gaming and video.', '2026-11-16 17:14:57.118406+00');
INSERT INTO public.spec_sheet VALUES (28, 28, 'Redmi 13C 5G brings high-speed 5G connectivity to the entry-level price segment. Its 90Hz display, 50MP main camera, and durable build quality make it a rapid volume mover for bulk retail procurement across regional markets.', '6.74-inch HD+ 90Hz Dot Drop display, 1600x720 pixels, Corning Gorilla Glass protection.', '50MP AI dual camera with HDR and Night mode, 1080p video recording.', 'MediaTek Dimensity 6100+ 5G processor (6nm), 4GB/6GB/8GB RAM.', '5000mAh battery with 18W charging support.', 'Low-power processor architecture ensuring cool touch temperatures throughout daily tasks.', '2026-11-16 17:14:57.119028+00');
INSERT INTO public.spec_sheet VALUES (29, 29, 'Motorola Edge 50 Ultra combines real Nordic wood and vegan leather backs with top-of-the-line specs. Its 144Hz curved pOLED screen, Pantone validated camera optics, and 125W TurboPower charging create a distinguished, luxurious device that attracts discerning retail consumers.', '6.7-inch Super HD 1.5K curved pOLED, 144Hz refresh rate, 2500 nits brightness, Pantone validated color accuracy.', '50MP main with OIS, 64MP 3x telephoto periscope with 100x hybrid zoom, 50MP ultra-wide with macro, Pantone validated skin tones.', 'Snapdragon 8s Gen 3, up to 16GB LPDDR5X RAM, 1TB UFS 4.0 storage, Moto AI.', '4500mAh battery with 125W TurboPower wired and 50W wireless charging.', 'Thermal management matrix using composite graphite layers to dissipate heat from the fast-charging battery.', '2026-11-16 17:14:57.119731+00');
INSERT INTO public.spec_sheet VALUES (30, 30, 'Motorola Edge 50 Pro introduces 125W hyper-charging and a flagship-grade 144Hz curved pOLED screen to the mid-premium wholesale market. With IP68 underwater protection and AI photo stabilization, it delivers outstanding value and strong sell-through.', '6.7-inch 1.5K curved pOLED, 144Hz, HDR10+, 2000 nits peak brightness, 100% DCI-P3 color gamut.', '50MP main with f/1.4 aperture and OIS, 10MP 3x telephoto with OIS, 13MP ultra-wide with macro.', 'Snapdragon 7 Gen 3, 8GB/12GB RAM, Hello UI based on Android 14.', '4500mAh cell with 125W TurboPower wired charging and 50W wireless charging.', 'Slim-profile heat transfer shield maintaining comfortable handling during fast charging sessions.', '2026-11-16 17:14:57.120367+00');
INSERT INTO public.spec_sheet VALUES (31, 31, 'Motorola Razr 50 Ultra sets the industry benchmark for flip foldables with its massive 4.0-inch external cover screen and dual 165Hz LTPO pOLED displays. Powered by Snapdragon 8s Gen 3, it offers snappy multitasking and high-fashion aesthetics that drive high margin sales.', 'Main: 6.9-inch Foldable LTPO pOLED, 165Hz, FHD+; Cover: 4.0-inch LTPO pOLED, 165Hz, 2400 nits.', 'Dual 50MP rear system: 50MP main with OIS, 50MP 2x telephoto camera, Moto AI photo processing.', 'Snapdragon 8s Gen 3, 12GB LPDDR5X RAM, Moto AI personal assistant.', '4000mAh battery with 45W TurboPower wired and 15W wireless charging.', 'Dual-part cooling distribution keeping the compact flip chassis cool while running dual 165Hz screens.', '2026-11-16 17:14:57.121048+00');
INSERT INTO public.spec_sheet VALUES (32, 32, 'Moto G84 5G is a wholesale bestseller combining 12GB RAM, 256GB storage, and a vibrant 120Hz pOLED screen at an unbeatable wholesale price. Its vegan leather design and Dolby Atmos sound make it an immediate favorite for budget-conscious retail store customers.', '6.55-inch FHD+ pOLED, 2400x1080 pixels, 120Hz refresh rate, 1300 nits peak, 10-bit billion color display.', '50MP Ultra Pixel main with OIS, 8MP ultra-wide with macro, stereo speakers with Dolby Atmos.', 'Snapdragon 695 5G (6nm), 12GB RAM standard, 256GB storage standard.', '5000mAh battery with 30W TurboPower charging.', 'Passive cooling layout optimized for everyday multitasking without thermal throttling.', '2026-11-16 17:14:57.121695+00');
